vec3 z = normalize(center - eye);
    vec3 x = normalize(cross(up, z));
    vec3 y = cross(z, x);

    mat4 result;
    result[0][0] = x.x;
    result[0][1] = x.y;
    result[0][2] = x.z;
    result[0][3] = -dot(x, eye);

    result[1][0] = y.x;
    result[1][1] = y.y;
    result[1][2] = y.z;
    result[1][3] = -dot(y, eye);

    result[2][0] = z.x;
    result[2][1] = z.y;
    result[2][2] = z.z;
    result[2][3] = -dot(z, eye);

    result[3][0] = 0;
    result[3][1] = 0;
    result[3][2] = 0;
    result[3][3] = 1;

    return result;
